L000041	\title{Weakly turbulent saturation of the nonlinear scalar ergoregion instability}
L000042	\author{Nils Siemonsen\orcidlink{0000-0001-5664-3521}}
L000043	\email[]{nils.siemonsen@princeton.edu}
L000044	
L000045	
L000046	
L000047	\affiliation{Princeton Gravity Initiative, Princeton University, Princeton, NJ 08544, USA}
L000048	\affiliation{Department of Physics, Princeton University, Princeton, NJ 08544, USA}
L000049	
L000050	
